<script setup lang="ts">
import { ref } from 'vue'
import { Bot, Send, Sparkles, Wrench } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
type Tool={tool:string;summary:string};type Evidence={type:string;name:string;detail:string};type Action={type:string;label:string;assetId?:string;runbookId?:string};type Citation={knowledgeId:string;title:string;category:string;snippet:string;score:number};type Answer={question:string;answer:string;tools:Tool[];evidence:Evidence[];actions:Action[];citations:Citation[];generatedAt:string}
const auth=useAuthStore();const question=ref('');const loading=ref(false);const error=ref('');const history=ref<Answer[]>([])
async function ask(){const text=question.value.trim();if(!text)return;loading.value=true;error.value='';try{const response=await fetch('/api/v1/aiops/agent/query',{method:'POST',headers:{Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'},body:JSON.stringify({question:text})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'AI Agent 请求失败');history.value.unshift(data);question.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'AI Agent 请求失败'}finally{loading.value=false}}
</script>
<template><section class="ai-agent"><header><div><span>AI OPERATIONS AGENT</span><h2>智能运维 Agent</h2><p>可查询 CMDB 资产、机房分布、设备配置、告警影响，并推荐排障知识。</p></div><Bot/></header><form @submit.prevent="ask"><input v-model="question" placeholder="例如：现在有多少台物理机？都在哪个机房？"><button class="primary" :disabled="loading||!question.trim()"><Send/>{{loading?'分析中':'提问'}}</button></form><div v-if="error" class="agent-error">{{error}}</div><div class="agent-examples"><button v-for="item in ['现在有多少台物理机？','物理机都在哪个机房？','查看 host-node01 的配置','当前有哪些严重告警？']" :key="item" @click="question=item">{{item}}</button></div><div class="agent-history"><article v-for="item in history" :key="item.generatedAt+item.question"><header><Sparkles/><b>{{item.question}}</b><span>{{item.generatedAt}}</span></header><p>{{item.answer}}</p><div v-if="item.tools.length" class="agent-tools"><span v-for="tool in item.tools" :key="tool.tool"><Wrench/>{{tool.tool}} · {{tool.summary}}</span></div><div v-if="item.evidence.length" class="agent-evidence"><article v-for="e in item.evidence" :key="e.name+e.detail"><b>{{e.name}}</b><span>{{e.type}} · {{e.detail}}</span></article></div><div v-if="item.citations.length" class="agent-citations"><span v-for="c in item.citations" :key="c.knowledgeId">[{{c.knowledgeId}}] {{c.title}}</span></div></article></div></section></template>
<style scoped>
.ai-agent{padding:18px;border:1px solid #173b55;background:#071925;color:#dcecff}.ai-agent>header{display:flex;justify-content:space-between;align-items:center}.ai-agent header span{color:#2ad1e7;font-size:10px;letter-spacing:.14em}.ai-agent h2{margin:5px 0}.ai-agent p{margin:0;color:#718ba2;font-size:12px}.ai-agent header svg{width:34px;color:#2ad1e7}.ai-agent form{display:flex;gap:8px;margin:16px 0}.ai-agent input{flex:1;height:38px;border:1px solid #22465f;background:#061725;color:#dcecff;padding:0 10px}.ai-agent button{display:inline-flex;align-items:center;gap:6px;border:1px solid #23455f;background:#0b263b;color:#bdd8e9;padding:8px 11px}.ai-agent button.primary{background:#087c9e}.agent-examples{display:flex;flex-wrap:wrap;gap:6px}.agent-examples button{font-size:10px}.agent-error{margin:10px 0;padding:9px;border:1px solid #783e49;background:#35161e;color:#ff9aa7}.agent-history{display:grid;gap:10px;margin-top:14px}.agent-history>article{padding:13px;border:1px solid #1b4b62;background:#081f31}.agent-history>article>header{display:flex;gap:7px;align-items:center}.agent-history header b{flex:1}.agent-history header span{color:#617e92;font-size:10px}.agent-history p{white-space:pre-wrap;margin:10px 0;color:#a9c0cf;line-height:1.7}.agent-tools,.agent-citations{display:flex;flex-wrap:wrap;gap:6px}.agent-tools span,.agent-citations span{padding:4px 7px;background:#10334a;color:#8fc6d8;font-size:10px}.agent-evidence{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:7px;margin-top:8px}.agent-evidence article{padding:8px;background:#061725}.agent-evidence b,.agent-evidence span{display:block}.agent-evidence span{color:#617e92;font-size:10px}
</style>
